import 'task_model.dart';

/// ============================================================
/// AI PLAN MODEL
/// ============================================================
///
/// Represents a complete plan generated by StudyX AI.
///
/// The model is intentionally tolerant when reading JSON so the
/// backend can evolve without constantly breaking the Flutter app.
///
/// ============================================================

class AiPlan {
  final String message;
  final List<AiPlanItem> items;

  /// Optional AI-generated title for the plan.
  final String? title;

  /// Optional explanation of the overall planning strategy.
  final String? strategy;

  /// Optional goal associated with the plan.
  final String? goal;

  /// Optional confidence score from 0.0 to 1.0.
  final double? confidence;

  /// Optional date/time when this plan was intended to start.
  final DateTime? startDate;

  /// Optional date/time when this plan was intended to end.
  final DateTime? endDate;

  const AiPlan({
    required this.message,
    required this.items,
    this.title,
    this.strategy,
    this.goal,
    this.confidence,
    this.startDate,
    this.endDate,
  });

  // ============================================================
  // TOTAL MINUTES
  // ============================================================

  int get totalMinutes {
    return items.fold(
      0,
      (total, item) =>
          total + item.estimatedMinutes,
    );
  }

  // ============================================================
  // TOTAL ITEMS
  // ============================================================

  int get totalItems {
    return items.length;
  }

  // ============================================================
  // HIGH PRIORITY ITEMS
  // ============================================================

  List<AiPlanItem> get highPriorityItems {
    return items
        .where(
          (item) => item.priority >= 8,
        )
        .toList();
  }

  // ============================================================
  // REVISION ITEMS
  // ============================================================

  List<AiPlanItem> get revisionItems {
    return items
        .where(
          (item) =>
              item.type == TaskType.revision,
        )
        .toList();
  }

  // ============================================================
  // STUDY ITEMS
  // ============================================================

  List<AiPlanItem> get studyItems {
    return items
        .where(
          (item) =>
              item.type == TaskType.study,
        )
        .toList();
  }

  // ============================================================
  // PRACTICE ITEMS
  // ============================================================

  List<AiPlanItem> get practiceItems {
    return items
        .where(
          (item) =>
              item.type == TaskType.practice,
        )
        .toList();
  }

  // ============================================================
  // TEST ITEMS
  // ============================================================

  List<AiPlanItem> get testItems {
    return items
        .where(
          (item) =>
              item.type == TaskType.test,
        )
        .toList();
  }

  // ============================================================
  // FROM JSON
  // ============================================================

  factory AiPlan.fromJson(
    Map<String, dynamic> json,
  ) {
    final rawItems =
        _extractList(
          json,
          const [
            'items',
            'tasks',
            'plan',
            'schedule',
          ],
        );

    final parsedItems =
        <AiPlanItem>[];

    for (final item in rawItems) {
      if (item is! Map) {
        continue;
      }

      try {
        parsedItems.add(
          AiPlanItem.fromJson(
            Map<String, dynamic>.from(
              item,
            ),
          ),
        );
      } catch (_) {
        // Ignore malformed individual items.
        // A single bad item should not destroy
        // the entire AI plan.
      }
    }

    return AiPlan(
      message: _string(
            json['message'] ??
                json['response'] ??
                json['reply'] ??
                json['text'],
          ) ??
          '',

      title: _string(
        json['title'] ??
            json['planTitle'] ??
            json['plan_title'],
      ),

      strategy: _string(
        json['strategy'] ??
            json['planningStrategy'] ??
            json['planning_strategy'],
      ),

      goal: _string(
        json['goal'] ??
            json['objective'],
      ),

      confidence: _parseDouble(
        json['confidence'],
      ),

      startDate: _parseDate(
        json['startDate'] ??
            json['start_date'] ??
            json['startsAt'],
      ),

      endDate: _parseDate(
        json['endDate'] ??
            json['end_date'] ??
            json['endsAt'],
      ),

      items: parsedItems,
    );
  }

  // ============================================================
  // TO JSON
  // ============================================================

  Map<String, dynamic> toJson() {
    return {
      'message': message,
      'title': title,
      'strategy': strategy,
      'goal': goal,
      'confidence': confidence,
      'startDate':
          startDate?.toIso8601String(),
      'endDate':
          endDate?.toIso8601String(),

      'items': items
          .map(
            (item) => item.toJson(),
          )
          .toList(),
    };
  }

  // ============================================================
  // EXTRACT LIST
  // ============================================================

  static List<dynamic> _extractList(
    Map<String, dynamic> json,
    List<String> keys,
  ) {
    for (final key in keys) {
      final value = json[key];

      if (value is List) {
        return value;
      }
    }

    return const [];
  }

  // ============================================================
  // STRING PARSER
  // ============================================================

  static String? _string(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    final text =
        value.toString().trim();

    if (text.isEmpty ||
        text.toLowerCase() == 'null') {
      return null;
    }

    return text;
  }

  // ============================================================
  // DOUBLE PARSER
  // ============================================================

  static double? _parseDouble(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    double? result;

    if (value is num) {
      result = value.toDouble();
    } else {
      result = double.tryParse(
        value.toString(),
      );
    }

    if (result == null) {
      return null;
    }

    // AI confidence is always normalized.
    return result.clamp(
      0.0,
      1.0,
    );
  }

  // ============================================================
  // DATE PARSER
  // ============================================================

  static DateTime? _parseDate(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    final text =
        value.toString().trim();

    if (text.isEmpty) {
      return null;
    }

    return DateTime.tryParse(
      text,
    );
  }

  @override
  String toString() {
    return 'AiPlan('
        'title: $title, '
        'items: ${items.length}, '
        'totalMinutes: $totalMinutes'
        ')';
  }
}

/// ============================================================
/// AI PLAN ITEM
/// ============================================================
///
/// One executable/plannable unit inside an AI-generated plan.
///
/// ============================================================

class AiPlanItem {
  final String title;
  final String description;

  final TaskType type;

  final int estimatedMinutes;
  final int priority;

  final String? subjectId;
  final String? subjectName;

  final String? chapterId;
  final String? chapterName;

  /// Optional task ID when the AI is planning around an
  /// already-existing task.
  final String? taskId;

  /// Optional deadline for this individual plan item.
  final DateTime? deadline;

  /// Optional start time.
  final DateTime? startTime;

  /// Optional end time.
  final DateTime? endTime;

  /// Optional AI-generated reason for choosing this item.
  final String? reason;

  /// Optional learning objective.
  final String? objective;

  /// Optional estimated difficulty.
  final int? difficulty;

  /// Optional progress value from 0.0 to 1.0.
  final double? progress;

  const AiPlanItem({
    required this.title,
    required this.description,
    required this.type,
    required this.estimatedMinutes,
    required this.priority,
    this.subjectId,
    this.subjectName,
    this.chapterId,
    this.chapterName,
    this.taskId,
    this.deadline,
    this.startTime,
    this.endTime,
    this.reason,
    this.objective,
    this.difficulty,
    this.progress,
  });

  // ============================================================
  // FROM JSON
  // ============================================================

  factory AiPlanItem.fromJson(
    Map<String, dynamic> json,
  ) {
    final minutes = _parseInt(
      json['estimatedMinutes'] ??
          json['estimated_minutes'] ??
          json['duration'] ??
          json['minutes'],
      30,
    );

    final priority = _parseInt(
      json['priority'],
      5,
    );

    final difficultyValue = _parseIntNullable(
      json['difficulty'] ??
          json['difficultyLevel'] ??
          json['difficulty_level'],
    );

    final progressValue =
        _parseProgress(
      json['progress'],
    );

    return AiPlanItem(
      title: _string(
            json['title'] ??
                json['name'] ??
                json['task'],
          ) ??
          'Study',

      description: _string(
            json['description'] ??
                json['details'] ??
                json['note'],
          ) ??
          '',

      type: _taskTypeFromString(
        json['type'] ??
            json['taskType'] ??
            json['task_type'],
      ),

      estimatedMinutes:
          minutes.clamp(
        1,
        1440,
      ),

      priority:
          priority.clamp(
        1,
        10,
      ),

      subjectId: _string(
        json['subjectId'] ??
            json['subject_id'],
      ),

      subjectName: _string(
        json['subjectName'] ??
            json['subject_name'] ??
            json['subject'],
      ),

      chapterId: _string(
        json['chapterId'] ??
            json['chapter_id'],
      ),

      chapterName: _string(
        json['chapterName'] ??
            json['chapter_name'] ??
            json['chapter'],
      ),

      taskId: _string(
        json['taskId'] ??
            json['task_id'],
      ),

      deadline: _parseDate(
        json['deadline'] ??
            json['dueDate'] ??
            json['due_date'],
      ),

      startTime: _parseDate(
        json['startTime'] ??
            json['start_time'] ??
            json['start'],
      ),

      endTime: _parseDate(
        json['endTime'] ??
            json['end_time'] ??
            json['end'],
      ),

      reason: _string(
        json['reason'] ??
            json['why'],
      ),

      objective: _string(
        json['objective'] ??
            json['learningObjective'] ??
            json['learning_objective'],
      ),

      difficulty:
          difficultyValue == null
              ? null
              : difficultyValue.clamp(
                  1,
                  10,
                ),

      progress: progressValue,
    );
  }

  // ============================================================
  // TO JSON
  // ============================================================

  Map<String, dynamic> toJson() {
    return {
      'title': title,
      'description': description,

      'type': type.name,

      'estimatedMinutes':
          estimatedMinutes,

      'priority': priority,

      'subjectId': subjectId,
      'subjectName': subjectName,

      'chapterId': chapterId,
      'chapterName': chapterName,

      'taskId': taskId,

      'deadline':
          deadline?.toIso8601String(),

      'startTime':
          startTime?.toIso8601String(),

      'endTime':
          endTime?.toIso8601String(),

      'reason': reason,
      'objective': objective,

      'difficulty': difficulty,
      'progress': progress,
    };
  }

  // ============================================================
  // TASK TYPE PARSER
  // ============================================================

  static TaskType _taskTypeFromString(
    dynamic value,
  ) {
    if (value == null) {
      return TaskType.study;
    }

    final normalized = value
        .toString()
        .trim()
        .toLowerCase()
        .replaceAll(
          '-',
          '_',
        )
        .replaceAll(
          ' ',
          '_',
        );

    switch (normalized) {
      case 'study':
      case 'learn':
      case 'learning':
        return TaskType.study;

      case 'revision':
      case 'revise':
      case 'review':
        return TaskType.revision;

      case 'practice':
      case 'question':
      case 'questions':
      case 'problem_solving':
        return TaskType.practice;

      case 'test':
      case 'mock':
      case 'mock_test':
      case 'exam':
        return TaskType.test;

      case 'backlog':
      case 'pending':
        return TaskType.backlog;

      case 'custom':
      case 'other':
        return TaskType.custom;

      default:
        // Also support exact enum names.
        for (final type
            in TaskType.values) {
          if (type.name
                  .toLowerCase() ==
              normalized) {
            return type;
          }
        }

        return TaskType.study;
    }
  }

  // ============================================================
  // INTEGER
  // ============================================================

  static int _parseInt(
    dynamic value,
    int fallback,
  ) {
    if (value is int) {
      return value;
    }

    if (value is num) {
      return value.toInt();
    }

    return int.tryParse(
          value?.toString() ?? '',
        ) ??
        fallback;
  }

  // ============================================================
  // NULLABLE INTEGER
  // ============================================================

  static int? _parseIntNullable(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    if (value is int) {
      return value;
    }

    if (value is num) {
      return value.toInt();
    }

    return int.tryParse(
      value.toString(),
    );
  }

  // ============================================================
  // PROGRESS
  // ============================================================

  static double? _parseProgress(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    double? result;

    if (value is num) {
      result = value.toDouble();
    } else {
      result = double.tryParse(
        value.toString(),
      );
    }

    if (result == null) {
      return null;
    }

    // Support AI sending 75 instead of 0.75.
    if (result > 1 && result <= 100) {
      result = result / 100;
    }

    return result.clamp(
      0.0,
      1.0,
    );
  }

  // ============================================================
  // HELPERS
  // ============================================================

  static String? _string(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    final text =
        value.toString().trim();

    if (text.isEmpty ||
        text.toLowerCase() == 'null') {
      return null;
    }

    return text;
  }

  static DateTime? _parseDate(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    final text =
        value.toString().trim();

    if (text.isEmpty) {
      return null;
    }

    return DateTime.tryParse(
      text,
    );
  }

  // ============================================================
  // DISPLAY HELPERS
  // ============================================================

  bool get isUrgent =>
      priority >= 8;

  bool get isLongTask =>
      estimatedMinutes >= 90;

  bool get isScheduled =>
      startTime != null ||
      endTime != null;

  bool get isOverdue {
    if (deadline == null) {
      return false;
    }

    return deadline!.isBefore(
      DateTime.now(),
    );
  }

  String get typeLabel {
    switch (type) {
      case TaskType.study:
        return 'Study';

      case TaskType.revision:
        return 'Revision';

      case TaskType.practice:
        return 'Practice';

      case TaskType.test:
        return 'Test';

      case TaskType.backlog:
        return 'Backlog';

      case TaskType.custom:
        return 'Custom';
    }
  }

  @override
  String toString() {
    return 'AiPlanItem('
        'title: $title, '
        'type: ${type.name}, '
        'minutes: $estimatedMinutes, '
        'priority: $priority'
        ')';
  }
}